-- koloni-243: Donanım listesi sürüm 2 — kullanıcı kararları (17.10.2026): önerilen parçalar, SHT41 (DHT22 yerine), arılık başına 1 gateway (LoRa düğümleri → gateway → 4G), 18650 + güneş isteğe bağlı.
-- Karara bağlanan kalemler «onaylandı – test edilecek»; açık kalan: pil kapasitesi, güneş paneli modeli. Yeni sürüm sa_donanim_surum'a ve değişiklik kaydına (sa_degisiklik) trigger ile yazılır, geri alınabilir.
update public.sa_donanim
   set data = $DON${"surum_notu": "Kullanıcı kararları 17.10.2026: önerilen parçalar, SHT41 (DHT22 yerine), arılık başına 1 gateway, LoRa + 4G, 18650 + güneş isteğe bağlı", "durum": "onaylandı – test edilecek (2 açık karar: pil kapasitesi, güneş paneli modeli)", "kalemler": [{"id": "node", "ad": "Kovan düğümü (mikrodenetleyici kartı)", "cihazTipi": "—", "rol": "Kovandaki sensörleri okur, ölçüm aralığına göre gönderir (LoRa / Wi‑Fi).", "adaylar": "Seçilen: LilyGO T-Weigh (ESP32, 4× HX711, SX1262 LoRa EU868, Wi‑Fi b/g/n, BLE 4.2, 4 MB flash, 5–12 V DC, I2S/I2C/SPI) — kovan başına 1 · alternatif (seçilmedi): ESP32-S3 kartı + ayrı LoRa + HX711", "gerekenOzellik": "I2S (SPH0645), I²C (SHT41, ADXL345), 1-Wire (DS18B20 giriş), 4 kanal tartı girişi (dahili HX711), IR kesme girişleri, derin uyku; T-Weigh'de USB-seri yok → T-U2T programlayıcı gerekir; LoRa ile arılığın tek gateway'ine gönderir", "kurallar": "Tüm sensör kuralları", "kaynak": "lilygo.cc/products/t-weigh · Espressif ESP32-S3 datasheet", "fiyat": "T-Weigh 20,88 USD (lilygo.cc, 17.10.2026)", "durum": "onaylandı – test edilecek"}, {"id": "isi_nem", "ad": "Kovan içi sıcaklık / nem", "cihazTipi": "isi_nem", "rol": "Kuluçka sıcaklığı, nem, yoğuşma, havalandırma, oğul öncesi sıcaklık, eşek arısı ani değişimi.", "adaylar": "Seçilen: Sensirion SHT41 (±0,2 °C tip., ±1,8 %RH tip., 1,08–3,6 V, I²C adres 0x44, −40…125 °C) — DHT22 yerine (DHT22 ±0,5 °C eşek arısı 0,5 °C sınırı için yetersiz) · alternatif (seçilmedi): SHT31-DIS", "gerekenOzellik": "Çözünürlük ≤0,1 °C ve doğruluk ≈±0,2 °C (eşek arısı kuralı 0,5 °C ani değişim arar); okuma 30 dk, tıslama/titreşimde ~2 dk hızlı okuma; firmware sürücüsü firmware/node/src/sensors/sht41.cpp (taslak, cihazda test edilecek)", "kurallar": "Koloni sönmüş, yavrusuz/anasız, havalandırma/yoğuşma, oğul öncesi sıcaklık, eşek arısı (sıcaklık değişimi)", "kaynak": "sensirion.com SHT41 / SHT31-DIS-B · DHT22 datasheet · DS18B20 datasheet", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "giris_sicak", "ad": "Giriş sıcaklık sensörü", "cihazTipi": "isi_nem (giriş)", "rol": "Kovan girişinde 44 °C üstü (eşek arısı top yapma) kontrolü.", "adaylar": "Seçilen (öneri korundu): DS18B20 su geçirmez prob (±0,5 °C, −55…+125 °C ölçüm aralığı, 1-Wire) · not: girişte de SHT41 kullanılabilir (aynı sürücü; düğümdeki iç SHT41 ile aynı I²C adresi 0x44 → ayrı I²C hattı gerekir). 44 °C eşiği için ±0,5 °C doğruluk yeterli", "gerekenOzellik": "Girişte ölçtüğünün kayıtta işaretlenmesi (konum=giriş); 30 dk okuma, eşek arısı burst ~2 dk", "kurallar": "Eşek arısı (giriş > 44 °C kritik)", "kaynak": "DS18B20 datasheet", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "dis_isi_nem", "ad": "Merkezi (dış) ısı / nem", "cihazTipi": "dis_isi_nem", "rol": "Dış hava; uçuşa uygun gün, beklenen aktivite modeli, yoğuşma farkı.", "adaylar": "Seçilen: SHT41 + radyasyon kalkanı (kalkan modeli: Veri yok) — arılık başına 1, gateway'e bağlı", "gerekenOzellik": "30 dk okuma; güneşten korumalı", "kurallar": "Beklenenden düşük aktivite, koloni sönmüş (dış ≥ 6 °C), yoğuşma, eşek arısı IR yolu (uygun uçuş günü)", "kaynak": "sensirion.com", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "tarti", "ad": "Tartı (yük hücreleri + ADC)", "cihazTipi": "tarti", "rol": "Ağırlık; bal akımı, tarlacı kaybı, ani kayıp/oğul, hırsızlık/devrilme, kış stoku.", "adaylar": "Seçilen: HX711 ×4 (T-Weigh üzerinde; 24 bit Σ∆, 10 veya 80 SPS, kazanç 128/64/32) + 4 köşe yük hücresi (model/kapasite: Veri yok) · platform: hardware/platform", "gerekenOzellik": "15 dk okuma; ≤0,1 kg çözünürlük (tarlacı kuralı tarlaciMinKg 0,1 kg); 1 kg ani düşüş (oğul çıktı doğrulama), 3 kg/6 saat ani kayıp", "kurallar": "Tarlacı kaybı, oğul çıktı (doğrulama), ani kayıp, koloni sönmüş, bal akımı/taşıma planı", "kaynak": "HX711 datasheet (Avia) · lilygo.cc T-Weigh", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "ses", "ad": "Mikrofon", "cihazTipi": "ses", "rol": "Oğul öncesi ses, ana ötmesi, rahatsızlık, eşek arısı tıslaması.", "adaylar": "Seçilen: Knowles SPH0645LM4H (I2S, saat 2,048–4,096 MHz → 32–64 kHz örnekleme, SNR 65 dB(A)) · alternatif (seçilmedi): TDK INMP441", "gerekenOzellik": "Örnekleme ≥ 32 kHz (eşek arısı tıslaması 4,5–7,3 kHz, esekMinOrneklemeHz 32000); cihaz örnekleme hızını (sr) göndermeli; ham ses LoRa'ya gitmez, kovanda özet çıkarılır", "kurallar": "Oğul öncesi (110 Hz, 300 Hz), ana ötmesi (400–500 Hz), rahatsızlık (300–450 Hz), eşek arısı tıslaması", "kaynak": "SPH0645LM4H datasheet (Knowles) · INMP441 datasheet (TDK InvenSense)", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "titresim", "ad": "İvmeölçer (titreşim)", "cihazTipi": "titresim", "rol": "Gece titreşimi (oğul hazırlığı), ana ötmesi, darbe/rahatsızlık, kış hareketsizliği.", "adaylar": "Seçilen: ADXL345 (ODR en çok 3200 Hz → bant ≈1600 Hz; ±2–16 g; 4 mg/LSB; I²C/SPI; 32 FIFO) · alternatif: ADXL355 (gürültü 22,5 µg/√Hz, ±2/4/8 g, 20 bit; daha hassas, daha pahalı)", "gerekenOzellik": "Analiz bandı 20–800 Hz (titOgulHz) → örnekleme ≥ 2 kHz (ADXL345 3,2 kHz ile yeterli ama sınıra yakın); darbe için ≥2 g aralık; kovan çerçevesine sabit montaj; cihaz darbe gücünü (g) ve ötme türünü göndermeli — şu an göndermiyor", "kurallar": "Oğul hazırlığı (titreşim), ana ötmesi, rahatsız edilme/darbe, kış hareketsizliği, eşek arısı (titreşim artışı)", "kaynak": "ADXL345 datasheet Rev. G · st.com LIS3DH · analog.com ADXL355", "fiyat": "ADXL345 1ku 3,74 USD'den · ADXL355 1ku 46,03 USD'den (analog.com)", "durum": "onaylandı – test edilecek"}, {"id": "ir", "ad": "IR giriş sayacı (çift ışınlı, çift yönlü)", "cihazTipi": "ir", "rol": "Giren/çıkan arı sayısı; kanal başına sayım.", "adaylar": "Seçilen yapı: çift ışınlı, çift yönlü, kanal başına sayım (her kanalda 2 kızılötesi verici/alıcı çifti → yön) · hardware/mounting/ir-entrance.md, 3D baskı giriş kapısı; belirli verici/alıcı parçası: Veri yok", "gerekenOzellik": "Her kanal için iki ışın (yön tayini), giren ve çıkan ayrı, kanal başına sayım (sayaç arızası kuralı kanal sıfır sayıyor mu bakar); dar kanal; güneş/yağmur koruması; propolis/çöp tıkanmasına karşı temizlenebilir; erkek arı ayrımı yok → «Erkek arı uçuşu» Veri yok", "kurallar": "İlaçlama şüphesi, dönmeyen tarlacı, beklenenden düşük aktivite, sayaç arızası, oğul çıktı, eşek arısı IR yolu, koloni sönmüş", "kaynak": "Odemer 2021 (kanal tıkanması) · repo hardware/mounting", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek"}, {"id": "gateway", "ad": "Ağ geçidi (gateway)", "cihazTipi": "gateway", "rol": "Kovan düğümlerinden LoRa alır, internete (4G / Wi‑Fi) iletir; ayarları düğümlere dağıtır.", "adaylar": "Seçilen: LilyGO T-Beam V1.2 (ESP32, SX1262 LoRa EU868 +22 dBm, AXP2101 PMU, 18650 yuvası, GNSS) + SIMCom A7670E (LTE Cat 1, LTE-FDD B1/B3/B5/B7/B8/B20, GSM 900/1800, 3,4–4,2 V) — ARILIK BAŞINA 1 gateway: LoRa düğümleri → arılığın tek gateway'i → 4G", "gerekenOzellik": "EU868 bandı; HTTPS POST /api/ingest; ayar indirme (ölçüm aralığı) ve düğümlere iletme; pil/şebeke durumu göndermeli (gateway pil kuralı); Cihazlar sayfası arılıkta >1 gateway ya da gateway'siz kovan cihazı görürse uyarır; LoRa menzili arazide doğrulanmalı", "kurallar": "Gateway çevrimdışı/pil uyarıları, tüm sensör verisinin buluta gelmesi", "kaynak": "lilygo.cc T-Beam · SIMCom A7670 series spec", "fiyat": "T-Beam SoftRF 40,98 USD (lilygo.cc, 17.10.2026)", "durum": "onaylandı – test edilecek"}, {"id": "aku", "ad": "Güç: kovan pili / gateway aküsü / güneş paneli", "cihazTipi": "aku_kovan · aku_merkez", "rol": "Düğüm ve gateway beslemesi; pil yüzdesi uygulamaya gelir.", "adaylar": "Seçilen: 18650 Li-ion (düğüm ve gateway) + güneş paneli isteğe bağlı · kapasite: Veri yok · güneş paneli / şarj devresi modeli: Veri yok (açık karar) · T-Weigh 5–12 V DC girişi", "gerekenOzellik": "Pil yüzdesi ve şarj durumu gönderilmeli (pil kuralları: %10 bitti, 7/14 gün tahmini); kapasite hesabı ölçüm aralığına bağlı — Veri yok", "kurallar": "Pil bitiyor / bitti, şarj, gateway pil", "kaynak": "lilygo.cc T-Beam / T-Weigh", "fiyat": "Veri yok", "durum": "onaylandı – test edilecek (kapasite ve güneş paneli modeli açık)"}, {"id": "kutu", "ad": "Kutu ve montaj", "cihazTipi": "—", "rol": "Elektroniği nem/yağmur/arılardan korur; sensör yerleşimi.", "adaylar": "Su geçirmez kutu (IP sınıfı ve model: Veri yok) · hardware/platform (tartı), hardware/mounting (IR, kovan), 3d-print/giris-kapisi", "gerekenOzellik": "Mikrofon ve ivmeölçer kovan içinde, propolise karşı korumalı (file); sıcaklık/nem kuluçka alanına yakın; anten dışarıda", "kurallar": "Tümü", "kaynak": "repo hardware/", "fiyat": "Veri yok", "durum": "taslak – kullanıcı onayı bekliyor"}, {"id": "kamera", "ad": "Kamera (ileride)", "cihazTipi": "kamera_kovan · kamera_arilik", "rol": "Varroa taşıyan arı, eşek arısı görüntü tanıma; fotoğraf.", "adaylar": "Veri yok (model seçilmedi)", "gerekenOzellik": "Görüntü modeli gerekir; tek tek arı izleme (varroa şüphesi kuralı için)", "kurallar": "Varroa şüphesi (beklemede)", "kaynak": "Veri yok", "fiyat": "Veri yok", "durum": "taslak – kullanıcı onayı bekliyor"}], "kararlar": [{"baslik": "Pil kapasitesi", "secenekler": "18650 hücre sayısı / mAh — Veri yok", "not": "Ölçüm aralığına ve LoRa gönderim sıklığına bağlı; sahada ölçülmeli"}, {"baslik": "Güneş paneli modeli", "secenekler": "Panel gücü (W) ve şarj devresi modeli — Veri yok", "not": "Güneş isteğe bağlı; arılık gölgesine bağlı"}], "verilenKararlar": [{"baslik": "Bağlantı türü", "karar": "LoRa (kovan düğümleri) + 4G gateway (T-Beam V1.2 + A7670E)", "not": "Kullanıcı kararı · 17.10.2026"}, {"baslik": "Gateway yerleşimi", "karar": "Arılık başına tek gateway", "not": "Kullanıcı kararı · 17.10.2026 · LoRa menzili arazide doğrulanmalı"}, {"baslik": "Düğüm kartı", "karar": "LilyGO T-Weigh", "not": "Kullanıcı kararı · 17.10.2026 · T-U2T programlayıcı gerekir"}, {"baslik": "Sıcaklık/nem sensörü", "karar": "SHT41 (kovan içi + dış); giriş DS18B20", "not": "Kullanıcı kararı · 17.10.2026"}, {"baslik": "Güç (tür)", "karar": "18650 Li-ion + güneş paneli isteğe bağlı", "not": "Kullanıcı kararı · 17.10.2026"}]}$DON$::jsonb,
       surum_notu = 'Kullanıcı kararları 17.10.2026 (koloni-243)',
       degistiren_email = 'sistem (kullanıcı kararı)'
 where id = 1 and (data -> 'verilenKararlar') is null;

update public.yapilacaklar
   set durum = 'tamam', guncelleme = now(),
       aciklama = aciklama || ' — 17.10.2026 karara bağlandı: LoRa + 4G, arılık başına 1 gateway (T-Beam V1.2 + A7670E), düğüm T-Weigh, SHT41, 18650 + güneş isteğe bağlı. Açık: pil kapasitesi, güneş paneli modeli.'
 where baslik = 'Donanım: açık kararlar (bağlantı, güç, gateway yerleşimi)' and durum <> 'tamam';

insert into public.yapilacaklar (baslik, aciklama)
select 'Donanım: pil kapasitesi ve güneş paneli modeli', '18650 + güneş isteğe bağlı kararlaştırıldı (17.10.2026). Hücre sayısı/mAh ve güneş paneli + şarj devresi modeli: Veri yok — ölçüm aralığı ve LoRa gönderim sıklığına göre sahada ölçülüp seçilmeli.'
where not exists (select 1 from public.yapilacaklar where baslik = 'Donanım: pil kapasitesi ve güneş paneli modeli');
